//! The header parser on a header generated by the real Verilator.

use std::path::Path;
use std::process::Command;

use simjig_build::PortDir::{self, In, InOut, Out};
use simjig_build::svtypes::ir::Storage;
use simjig_build::svtypes::width::packed_storage;
use simjig_build::{HeaderPort, check_ports, read_header_ports};

use crate::support::{Sandbox, fixtures, real_verilator};

#[test]
fn parses_a_real_verilator_header() {
    let s = Sandbox::new();
    let obj = s.path().join("obj");
    let status = Command::new(real_verilator())
        .args(["--cc", "--prefix", "Vports", "-Mdir"])
        .arg(&obj)
        .arg(fixtures().join("rtl/ports.sv"))
        .status()
        .unwrap();
    assert!(status.success());
    let ports = read_header_ports(&obj.join("Vports.h")).unwrap();

    // Expected values written from the SV declarations in `ports.sv` by hand.
    let want: Vec<(&str, PortDir, u32, u32, Storage)> = vec![
        ("b1", In, 0, 0, Storage::CData),
        ("c8", In, 7, 0, Storage::CData),
        ("s9", In, 8, 0, Storage::SData),
        ("s16", Out, 15, 0, Storage::SData),
        ("i17", In, 16, 0, Storage::IData),
        ("i32", Out, 31, 0, Storage::IData),
        ("q33", In, 32, 0, Storage::QData),
        ("q64", Out, 63, 0, Storage::QData),
        ("w65", In, 64, 0, Storage::VlWide { words: 3 }),
        ("w128", Out, 127, 0, Storage::VlWide { words: 4 }),
        ("off", Out, 5, 2, Storage::CData),
        ("bidir", InOut, 3, 0, Storage::CData),
    ];
    let expected: Vec<HeaderPort> = want
        .into_iter()
        .map(|(name, dir, msb, lsb, storage)| HeaderPort {
            name: name.to_owned(),
            dir,
            msb,
            lsb,
            storage,
        })
        .collect();
    // Verilator groups declarations by storage, so compare ignoring order.
    assert_eq!(check_ports(&ports, &expected), Ok(()), "{ports:#?}");
    for p in &ports {
        assert_eq!(p.storage, packed_storage(p.width()).unwrap(), "{p}");
    }
}

/// The C ABI version is spelled three times: in the C header the shim compiles against,
/// in the runtime that checks it at load (`simjig::model::abi`), and here, where it keys
/// the cache. They must be bumped together.
#[test]
fn abi_version_is_the_same_in_header_runtime_and_build() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let header = std::fs::read_to_string(root.join("cpp/simjig_abi.h")).unwrap();
    let header: u32 = header
        .lines()
        .find_map(|l| l.strip_prefix("#define SIMJIG_ABI_VERSION "))
        .expect("SIMJIG_ABI_VERSION in simjig_abi.h")
        .trim()
        .trim_end_matches('u')
        .parse()
        .unwrap();
    let runtime = std::fs::read_to_string(root.join("../simjig/src/model/abi.rs")).unwrap();
    let runtime: u32 = runtime
        .lines()
        .find_map(|l| {
            l.trim()
                .strip_prefix("pub(crate) const ABI_VERSION: u32 = ")
        })
        .expect("ABI_VERSION in simjig::model::abi")
        .trim_end_matches(';')
        .parse()
        .unwrap();
    assert_eq!(
        (header, runtime),
        (simjig_build::ABI_VERSION, simjig_build::ABI_VERSION)
    );
}
